def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n):
    if n == 1:
        # tau(1^12) = tau(1) = 1. But the loop starts at n=2.
        return 1

    factors = prime_factorization(n)

    # If n = p1^a1 * p2^a2 * ..., then n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...

    tau = 1
    for exponent_a in factors.values():
        tau *= (12 * exponent_a + 1)
    return tau

solutions = []
for n in range(2, 101):
    tau_val = tau_n_12(n)
    if n == tau_val:
        solutions.append(n)

print("Solutions found in the range [2, 100]:", solutions)

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n):
    if n == 1:
        # tau(1^12) = tau(1) = 1. So n=1 is a solution.
        return 1

    factors = get_prime_factorization(n)
    tau_val = 1

    # If n = p1^a1 * ... * pk^ak, then tau(n^12) = (12*a1 + 1) * ... * (12*ak + 1)
    for prime, exponent in factors.items():
        tau_val *= (12 * exponent + 1)

    return tau_val

def check_solutions(start, end):
    solutions = []
    # The prompt requires checking 101 up to 5000.
    print(f"Checking integers n from {start} to {end}...")

    for n in range(start, end + 1):
        tau_val = tau_n_12(n)
        if n == tau_val:
            solutions.append(n)
    return solutions

